function* count() {
  let n = 1
  yield n
  n += 1
  return n
}

const it = count()
it.next() // { value: 1, done: false }
it.next() // { value: 2, done: true }

function* task() {
  yield { type: 'progress', value: 50 }
  return { type: 'terminal', reason: 'complete' }
}

const it = task()
it.next() // progress, done: false
it.next() // terminal, done: true

function* guarded() {
  try {
    yield 'waiting'
  } catch (error) {
    yield `recovered: ${error.message}`
  } finally {
    cleanup()
  }
}

const it = guarded()
it.next()
it.throw(new Error('cancel'))

async function* query() {
  yield { type: 'message_delta', text: '안' }
  yield { type: 'message_delta', text: '녕' }
  return { reason: 'end_turn' }
}

for await (const event of query()) {
  projectToUI(event)
}
